<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import {ResourceServices,RESOURCE_KINDS,type ResourceItem,type ResourceKind} from './resource-services';
 export let companyId:string;export let actorId:string;export let accessSignal:AbortSignal;export let kinds:string[]=[];
 const dispatch=createEventDispatcher();let service:ResourceServices|null=null,rows:ResourceItem[]=[],unavailable:ResourceKind[]=[],query='',loading=true,error='',opening='',mounted=false,seen='',seenSignal:AbortSignal,detach=()=>{};
 $: filtered=rows.filter(r=>(r.title+' '+r.ref.kind).toLowerCase().includes(query.toLowerCase()));
 function clear(){service?.close();service=null;rows=[];unavailable=[];query='';opening='';loading=false;}
 function fail(e:any){if(e.name==='AbortError')return;error=e.message||'Resources are unavailable.';if(e.status===401||e.companyDenied){clear();dispatch('denied',{status:e.status});}}
 async function load(){const current=service;if(!current)return;loading=true;error='';try{const result=await current.list(kinds.filter(k=>RESOURCE_KINDS.includes(k as ResourceKind)) as ResourceKind[]);if(current!==service)return;current.current();rows=result.items;unavailable=result.unavailable;}catch(e){if(current===service){rows=[];fail(e);}}finally{if(current===service)loading=false;}}
 async function open(row:ResourceItem){const current=service;if(!current||opening)return;opening=row.ref.kind+row.ref.id;error='';try{await current.snapshot(row.ref);if(current!==service)return;current.current();dispatch('open',{...row.ref});}catch(e){if(current===service)fail(e);}finally{if(current===service)opening='';}}
 function start(){detach();clear();seen=companyId+'|'+actorId+'|'+kinds.join(',');seenSignal=accessSignal;service=new ResourceServices(companyId,actorId,accessSignal);const signal=accessSignal;const abort=()=>clear();signal.addEventListener('abort',abort,{once:true});detach=()=>signal.removeEventListener('abort',abort);void load();}
 $: if(mounted&&(seen!==companyId+'|'+actorId+'|'+kinds.join(',')||seenSignal!==accessSignal))start();
 function session(e:StorageEvent){if(e.key==='token'||e.key===null){clear();dispatch('denied',{status:401});}}
 onMount(()=>mounted=true);onDestroy(()=>{detach();clear();});
</script>
<svelte:window on:storage={session}/>
<section class="picker" aria-label="Company resources"><header><h2>Company resources</h2><button aria-label="Close resource picker" on:click={()=>dispatch('close')}>×</button></header><div class="search"><input aria-label="Search company resources" placeholder="Find a resource…" bind:value={query}/><button disabled={loading||!!opening} on:click={load}>Refresh</button></div>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="list">{#if loading}<p class="empty" role="status">Loading authorized resources…</p>{:else}{#each filtered as row(row.ref.kind+row.ref.id)}<button class="row" disabled={!!opening} on:click={()=>open(row)}><span class="icon">{row.ref.kind==='sheet'?'▦':row.ref.kind==='email'?'✉':'▤'}</span><span><strong>{row.title}</strong><small>{row.ref.kind} · Revision {row.revision}</small></span><span class="arrow">{opening===row.ref.kind+row.ref.id?'…':'↗'}</span></button>{:else}<p class="empty">{query?'No matching resources.':'No accessible resources in the verified lists.'}</p>{/each}{/if}</div>{#if unavailable.length}<footer>Unavailable lists: {unavailable.join(', ')}. Other resources remain accessible.</footer>{/if}</section>
<style>.picker{background:#fff;border:1px solid #e6ebf4;border-radius:14px;box-shadow:0 12px 45px #17243f12;color:#17243f;width:min(420px,calc(100vw - 32px));max-height:70dvh;display:flex;flex-direction:column;overflow:hidden}header{display:flex;align-items:center;justify-content:space-between;padding:18px 18px 12px}h2{font-size:14px;font-weight:550;margin:0}button,input{font:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}header button{border:0;background:none;color:#9aa7bc;font-size:22px}.search{display:flex;gap:8px;padding:0 16px 12px}.search input{border:1px solid #e6ebf4;border-radius:8px;background:#f6f8fc;min-width:0;width:100%;padding:9px 11px;font-size:12px}.search button{border:0;background:none;color:#8c9ab0;font-size:10px}.list{overflow:auto;min-height:0;padding:0 8px 8px}.row{display:flex;align-items:center;gap:11px;width:100%;text-align:left;padding:13px 11px;border:0;background:none;border-radius:8px;color:inherit}.row:hover{background:#f6f8fc}.row strong{font-size:12px;font-weight:500;display:block;overflow-wrap:anywhere}.row small{display:block;font-size:10px;color:#a1acbd;margin-top:3px}.icon{display:grid;place-items:center;width:30px;height:30px;border-radius:7px;background:#eef3ff;color:#7291d5;flex:none}.arrow{margin-left:auto;color:#a6b2c4;font-size:12px}.empty{font-size:12px;text-align:center;color:#9ba7ba;padding:28px 16px}.error{font-size:12px;color:#ad4b52;padding:0 18px;overflow-wrap:anywhere}footer{padding:12px 17px;border-top:1px solid #edf1f7;font-size:10px;line-height:1.7;color:#a2adbd}button:focus-visible,input:focus-visible{outline:2px solid #789bff;outline-offset:2px}</style>
